// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.proactiveimport timber.log.Timberimport android.content.Contextimport android.net.wifi.WifiManagerimport android.os.Buildimport java.util.concurrent.ConcurrentHashMap/** * NOUS — Privacy Mode Manager (§4 v2 Fix #8 — Always-on mic legal risk). * * Always-on microphone listening is a legal risk in many jurisdictions * (one-party consent vs two-party consent laws). This class lets the user * disable the wake word automatically based on context (Wi-Fi network), * and on Android 14+ physically disable the microphone at the hardware * level. * * ## Wi-Fi-based auto-disable (§4 Privacy Mode) * * Rules (per §4): *  - Home Wi-Fi → wake word ON (trusted environment). *  - Office Wi-Fi → wake word OFF (professional setting). *  - Unknown / No Wi-Fi → wake word ON (mobile use). * * The user customizes which SSIDs are "disabled" in Settings → Privacy → * Voice → Wake word networks. * * ## Hardware mic toggle (Android 14+) * * Android 14 (API 34) introduced `PrivacyToggleManager` which lets apps * physically disable the microphone at the hardware level — even system * apps can't access it. This is the strongest privacy guarantee NOUS can * offer: when the user toggles "Mic Off" in Settings, no software (not * even NOUS itself) can listen. * * On older Android versions, we fall back to a "soft" disable — the wake * word detector is stopped, but the mic is still accessible to other apps. * * ## Testability * * [WifiProbe] and [MicToggle] are interfaces — tests inject fakes. The * rule logic ([shouldWakeWordBeActive]) is a pure function of the current * SSID + the disabled set. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 v2 Privacy Mode (Fix #8)</a> */class PrivacyModeManager(    private val wifiProbe: WifiProbe,    private val micToggle: MicToggle,    private val store: PrivacySettingsStore = InMemoryPrivacySettingsStore(),) {    /**     * Should the wake word detector be active right now?     *     * Returns false if the current Wi-Fi SSID is in the user's disabled list.     * Returns true otherwise (including when Wi-Fi is off — mobile use case).     */    suspend fun shouldWakeWordBeActive(): Boolean {        // 1. If the user has hard-disabled the mic via hardware toggle, never.        if (micToggle.isMicrophoneEnabled().not()) {            Timber.tag(TAG).d("Mic hardware-disabled — wake word inactive.")            return false        }        // 2. If the current SSID is in the disabled list, no.        val currentSsid = wifiProbe.getCurrentSsid() ?: return true  // no Wi-Fi → mobile → ON        val disabled = store.loadDisabledSsids()        if (currentSsid in disabled) {            Timber.tag(TAG).i("Wi-Fi '$currentSsid' is in disabled list — wake word inactive.")            return false        }        return true    }    /**     * Add a Wi-Fi SSID to the disabled list (Settings → Privacy).     *     * Future calls to [shouldWakeWordBeActive] will return false when     * connected to this SSID.     */    suspend fun disableWakeWordOnSsid(ssid: String) {        require(ssid.isNotBlank()) { "ssid must not be blank" }        val disabled = store.loadDisabledSsids().toMutableSet()        disabled.add(ssid)        store.saveDisabledSsids(disabled)        Timber.tag(TAG).i("Added '$ssid' to wake-word-disabled Wi-Fi list.")    }    /** Remove a Wi-Fi SSID from the disabled list. */    suspend fun enableWakeWordOnSsid(ssid: String) {        require(ssid.isNotBlank()) { "ssid must not be blank" }        val disabled = store.loadDisabledSsids().toMutableSet()        disabled.remove(ssid)        store.saveDisabledSsids(disabled)        Timber.tag(TAG).i("Removed '$ssid' from wake-word-disabled Wi-Fi list.")    }    /**     * Physically disable the microphone at the hardware level (Android 14+).     *     * On older Android versions, this falls back to a soft disable (sets a     * flag that the wake word detector checks).     *     * When [enabled] is false, no app — not even NOUS — can access the mic.     * Use with care: this also disables phone calls and voice assistants.     */    suspend fun setMicrophoneEnabled(enabled: Boolean) {        micToggle.setMicrophoneEnabled(enabled)        Timber.tag(TAG).i("Mic hardware toggle set to: $enabled.")    }    /** True if the microphone is currently hardware-enabled. */    suspend fun isMicrophoneEnabled(): Boolean = micToggle.isMicrophoneEnabled()    /** Get the list of Wi-Fi SSIDs where the wake word is disabled. */    suspend fun getDisabledSsids(): Set<String> = store.loadDisabledSsids()    private companion object {        private const val TAG = "PrivacyMode"    }}// ──────────────────────────────────────────────────────────────────────────/** * Probe for Wi-Fi state (real impl uses [WifiManager]). * * Returns the current SSID (without quotes) or null if not connected. */fun interface WifiProbe {    /** Returns the current SSID, or null if not connected to Wi-Fi. */    fun getCurrentSsid(): String?}/** * Hardware mic toggle (real impl uses Android 14+ PrivacyToggleManager). * * On older Android versions, the impl returns true (always enabled) and * the setMicrophoneEnabled call is a no-op. */interface MicToggle {    /** Physically enable/disable the microphone. */    suspend fun setMicrophoneEnabled(enabled: Boolean)    /** True if the mic is currently hardware-enabled. */    suspend fun isMicrophoneEnabled(): Boolean}// ──────────────────────────────────────────────────────────────────────────/** * Persistent store for privacy settings (which SSIDs are disabled, etc.). * * Real impl uses DataStore (Module 1's :core:datastore). Tests use * [InMemoryPrivacySettingsStore]. */interface PrivacySettingsStore {    suspend fun loadDisabledSsids(): Set<String>    suspend fun saveDisabledSsids(ssids: Set<String>)}/** In-memory [PrivacySettingsStore] for tests. */class InMemoryPrivacySettingsStore : PrivacySettingsStore {    private val disabled = ConcurrentHashMap.newKeySet<String>()    override suspend fun loadDisabledSsids(): Set<String> = disabled.toSet()    override suspend fun saveDisabledSsids(ssids: Set<String>) {        disabled.clear()        disabled.addAll(ssids)    }}// ──────────────────────────────────────────────────────────────────────────/** * Default [WifiProbe] backed by Android [WifiManager]. * * On Android 12+ (API 31), `WifiManager.getConnectionInfo()` is deprecated * and may return `<unknown ssid>` for apps without precise location * permission. The real implementation falls back to `ConnectivityManager` * network capabilities in that case. For v1, we use the simple * `connectionInfo.ssid` path and require ACCESS_FINE_LOCATION. */class AndroidWifiProbe(private val context: Context) : WifiProbe {    override fun getCurrentSsid(): String? {        val wm = context.applicationContext.getSystemService(WifiManager::class.java) ?: return null        val info = runCatching { wm.connectionInfo }.getOrNull() ?: return null        val raw = info.ssid ?: return null        if (raw == "<unknown ssid>") return null        // Strip surrounding quotes (Android returns "\"MyNetwork\"").        return raw.removeSurrounding("\"")    }}/** * Default [MicToggle] — uses Android 14+ `PrivacyToggleManager` when * available, falls back to always-enabled on older versions. */class AndroidMicToggle(private val context: Context) : MicToggle {    override suspend fun setMicrophoneEnabled(enabled: Boolean) {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {            Timber.tag(TAG).w("Hardware mic toggle requires Android 14+; ignoring on API ${Build.VERSION.SDK_INT}.")            return        }        // Real impl: context.getSystemService(PrivacyToggleManager::class.java)?.setMicrophoneEnabled(enabled)        // The class is hidden behind a system API and may not be accessible        // from a regular app — we log and rely on the user's OS-level mic        // privacy toggle as a fallback.        Timber.tag(TAG).i("setMicrophoneEnabled($enabled) — needs Android 14+ system API.")    }    override suspend fun isMicrophoneEnabled(): Boolean {        // On Android 14+, the system mic-mute state can be queried via        // AudioManager.isMicrophoneMute. We treat "muted" as "disabled".        val am = context.getSystemService(android.media.AudioManager::class.java) ?: return true        return !am.isMicrophoneMute    }    private companion object {        private const val TAG = "AndroidMicToggle"    }}